{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Absolute oral bioavailability of testosterone in humans is 3.6 ± 2.5%, well below 20%; testosterone shares the unmodified 3-keto-4-ene androstane core with the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Oral testosterone bioavailability is 2–8% because of intestinal and hepatic first-pass metabolism, indicating that the query's steroid core is subject to extensive presystemic clearance.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Progesterone has low oral bioavailability due to limited solubility and extensive gut/liver metabolism; it shares the 3-keto-4-ene steroid framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Testosterone undecanoate, a lipophilic ester prodrug, has absolute oral bioavailability of 6.8 ± 3.3%, showing that lipophilicity alone does not raise steroid F above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Medroxyprogesterone acetate has oral bioavailability probably less than 15%, below the 20% threshold, supporting low F for a 3-keto-4-ene steroid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Ethinylestradiol has 25–65% oral bioavailability, but its aromatic A ring and 17α-ethinyl group reduce first-pass metabolism; the query has a 3-keto-4-ene, 17-keto steroid, so this high-F result does not transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "17-Methyltestosterone has good oral bioavailability, but this is due to 17α-methylation blocking first-pass metabolism; the query lacks this protective modification.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C48"],
      "claim": "Norethindrone has approximately 80% oral bioavailability, but it is a 19-nor steroid with a 17α-ethinyl group, structurally distinct from the query's 17-keto androstane.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C22"],
      "claim": "Cortisone has ~85% oral bioavailability, but it is a corticosteroid with a dihydroxyacetone side chain, not a 17-keto androstenedione; transferability to the query is low.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 17-keto androstenedione-type steroid (4-hydroxyandrostenedione). The closest unmodified 3-keto-4-ene steroid analogues—testosterone, progesterone, testosterone undecanoate, and medroxyprogesterone acetate—show oral bioavailability below 20% due to extensive first-pass metabolism. High-bioavailability analogues owe their oral activity to protective 17α-substituents, aromatic A rings, or corticosteroid side chains absent in the query. Therefore, F >= 20% is not supported; predict low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule (4-hydroxyandrostenedione/formestane) in humans.",
    "No retrieved record for the exact query; predictions rely on steroid analogues with moderate Morgan similarity.",
    "Some high-bioavailability records involve structural modifications that alter first-pass metabolism, limiting direct transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

